selection_bias_sensitivity<-function(candidates,evaluation_rows,selection_results,design,reference_model_id,uncertainty='none',cluster_resamples=NULL,confidence_level=.95,outcome_comparability=NULL,tolerance=1e-10,context=NULL){
 d<-.vb_design(design,context);rows<-.vb_records(evaluation_rows,d);cc<-.vs_index(candidates,'model_id','candidates');candidates<-cc$rows;cm<-cc$index;if(!length(candidates)||!(reference_model_id%in%names(cm))).cr_error('VALIDATION_CANDIDATES','Reference candidate must exist');tol<-.vb_number(tolerance,'tolerance',0);rr<-.vs_index(rows,'application_id','evaluation rows');ids<-vapply(rows,function(r)r$application_id,character(1));if(!length(rows)).cr_error('VALIDATION_POPULATION','Nonempty through-the-door population required');draws<-.vb_draws(uncertainty,cluster_resamples,rows,confidence_level);prepared<-rows;exclusions<-list();pre_reasons<-list();weights<-numeric(length(rows))
 for(i in seq_along(rows)){r<-rows[[i]];weights[i]<-.vb_number(if(is.null(r$weight))1 else r$weight,'weight',0);if(!is.logical(r$funded)||length(r$funded)!=1L||is.na(r$funded)).cr_error('VALIDATION_SELECTION','funded must explicitly be Boolean');reason<-NULL;if(r$horizon_end>d$evaluation_cutoff)reason<-'IMMATURE_HORIZON' else if(is.null(r$known_at)||.cr_data_date(r$known_at,'known_at')>.cr_data_date(d$evaluation_cutoff,'cutoff'))reason<-'OUTCOME_NOT_YET_KNOWN' else if(r$label_origin%in%c('OBSERVED_OWN_CONTRACT','AUTHORIZED_EXPLORATION','EXTERNAL_CONTRACT','SYNTHETIC_TRUTH')&&identical(as.numeric(r$outcome),0)&&(is.null(r$complete_through)||.cr_data_date(r$complete_through,'complete_through')<.cr_data_date(r$horizon_end,'end')))reason<-'INCOMPLETE_NEGATIVE_COVERAGE';if(!is.null(reason)){pre_reasons[[r$application_id]]<-reason;prepared[[i]]$label_origin<-'UNOBSERVED';prepared[[i]]$known_at<-d$evaluation_cutoff;prepared[[i]]['outcome']<-list(NULL)};prepared[[i]]$mature<-r$horizon_end<=d$evaluation_cutoff}
 if(sum(weights)<=0).cr_error('VALIDATION_WEIGHTS','Positive target population mass required');ev<-prepare_reject_evaluation(candidates,prepared,as_of=d$evaluation_cutoff,target=d$target,outcome_comparability=outcome_comparability)$value;scopes<-setNames(ev$rows,vapply(ev$rows,function(r)r$application_id,character(1)));flags<-list();for(f in ev$contamination_flags)flags[[f$application_id]]<-c(flags[[f$application_id]],f$reason)
 for(r in rows){key<-r$application_id;s<-scopes[[key]];if(!s$validation_eligible){reason<-pre_reasons[[key]];if(is.null(reason))reason<-if(length(flags[[key]]))flags[[key]][1]else'NO_OBSERVED_TRUTH';exclusions[[length(exclusions)+1L]]<-list(prediction_id=r$prediction_id,reason=reason)}}
 predictions<-list();for(cand in candidates){pp<-.vs_index(cand$predictions,'application_id','candidate predictions');pm<-pp$index;if(!setequal(names(pm),ids)).cr_error('VALIDATION_POPULATION','Every frozen candidate must cover exact same through-the-door cases');values<-numeric(length(rows));for(i in seq_along(rows)){r<-rows[[i]];f<-pm[[r$application_id]];p<-.vb_number(f$pd,'pd',0);if(p>1).cr_error('VALIDATION_PROBABILITY','PD exceeds one');if(.cr_data_date(f$known_at,'prediction known_at')>.cr_data_date(r$as_of,'as_of')).cr_error('VALIDATION_LOOKAHEAD','Candidate prediction became known after application index');if(f$known_at<cand$training_known_at).cr_error('VALIDATION_LOOKAHEAD','Prediction predates frozen training');values[i]<-p};predictions[[cand$model_id]]<-values}
 assess<-function(mult=NULL){result<-structure(list(),names=character());contrasts<-structure(list(),names=character());scope_names<-sort(unique(vapply(Filter(function(s)s$validation_eligible,scopes),function(s)s$evidence_scope,character(1))));for(scope in scope_names){result[[scope]]<-list();for(model in names(predictions)){pred<-predictions[[model]];metric_rows<-lapply(seq_along(rows),function(i){r<-rows[[i]];s<-scopes[[r$application_id]];list(eligible=s$validation_eligible&&s$evidence_scope==scope,weight=weights[i]*if(is.null(mult))1 else mult[i],target=r$outcome,pd=pred[i],cluster_id=r$cluster_id)});result[[scope]][[model]]<-.mm_metrics(metric_rows)};ref<-result[[scope]][[reference_model_id]];for(model in names(result[[scope]])){m<-result[[scope]][[model]];for(key in c('brier','auc','calibration_error','log_loss')){a<-m[[key]];b<-ref[[key]];contrasts[paste(scope,model,key,sep='|')]<-list(if(is.null(a)||is.null(b))NULL else a-b)}}};list(metrics=result,contrasts=contrasts)}
 measured<-assess();bands<-.vb_bands(if(is.null(draws))NULL else lapply(draws,function(x)assess(x)$contrasts),confidence_level);factual<-vapply(rows,function(r){s<-scopes[[r$application_id]];as.numeric(s$validation_eligible&&s$evidence_scope%in%c('FUNDED_OBSERVED_TEST','OBSERVED_EXPLORATION'))},numeric(1));outcomes<-lapply(seq_along(rows),function(i)if(factual[i]==1)rows[[i]]$outcome else NULL);scenarios<-list();violations<-list();selection_results<-.vs_index(selection_results,'result_id','selection results')$rows;methods<-list(IPW=selection_ipw_weights,BOUNDS=reject_inference_bounds,MNAR_SHIFT=reject_inference_sensitivity,AIPW=estimate_population_risk_aipw)
 for(record in selection_results){kind<-record$kind;model<-record$model_id;if(!(kind%in%names(methods))||!(model%in%names(cm))).cr_error('VALIDATION_SELECTION','Known arithmetic kind and frozen candidate required');if(!identical(record$population_id,d$population_id)||.cr_hash(record$target)!=.cr_hash(d$target)||!identical(as.character(unlist(record$application_ids)),ids)).cr_error('VALIDATION_POPULATION','Selection result must bind exact ordered population and target');inputs<-record$inputs;if(!.cr_object(inputs)||'context'%in%names(inputs)).cr_error('VALIDATION_SELECTION','Fixed arithmetic inputs required');if(.cr_hash(inputs$observed)!=.cr_hash(as.list(factual))||.cr_hash(inputs$target_weights)!=.cr_hash(as.list(weights))).cr_error('VALIDATION_SELECTION','Arithmetic sample and weights must match actual mature funded evidence');if(kind!='IPW'&&.cr_hash(inputs$outcomes)!=.cr_hash(outcomes)).cr_error('VALIDATION_SELECTION','Pseudo/synthetic/proxy labels cannot replace funded truth');if(kind=='MNAR_SHIFT'&&.cr_hash(inputs$baseline_pd)!=.cr_hash(as.list(predictions[[model]]))).cr_error('VALIDATION_SELECTION','MNAR baseline differs from frozen predictions');if(kind=='AIPW'){lineage<-inputs$fold_lineage$rows;if(length(lineage)!=length(rows)||any(vapply(seq_along(rows),function(i){m<-lineage[[i]];r<-rows[[i]];!identical(m$entity_id,r$entity_id)||!identical(m$as_of,r$as_of)||m$features_known_at>r$as_of||!identical(m$label_known_at,r$known_at)},logical(1)))).cr_error('VALIDATION_SELECTION','OOF nuisance lineage must bind actual ordered evaluation entities and dates')};overlap<-NULL;computed<-NULL;status<-'ASSUMPTION_CONDITIONAL'
 if(kind%in%c('IPW','AIPW')){prop<-inputs$propensities;if(is.list(prop)&&length(prop)&&is.list(prop[[1]]))prop<-do.call(rbind,lapply(prop,unlist))else if(is.list(prop))prop<-as.numeric(unlist(prop));if(!is.numeric(prop)||any(!is.finite(prop))||any(prop<0|prop>1)||if(is.null(dim(prop)))length(prop)!=length(rows)else nrow(prop)!=length(rows)).cr_error('VALIDATION_SELECTION','Aligned finite propensity probabilities required');joint<-if(is.null(dim(prop)))prop else apply(prop,1,prod);if(any(joint==0&factual==1)).cr_error('VALIDATION_SELECTION','Observed cases cannot have zero propensity');missing<-sum(weights[joint==0]);overlap<-list(minimum_propensity=min(joint),maximum_propensity=max(joint),zero_support_target_mass=missing,full_population_identified_under_mar=missing==0);trim<-as.numeric(unlist(inputs$trim));retained<-if(kind=='IPW'&&length(trim))joint>=trim[1]&joint<=trim[2]else rep(TRUE,length(rows));if(any(joint==0&weights>0&retained))status<-'NOT_IDENTIFIED_ZERO_SUPPORT'}
 if(status!='NOT_IDENTIFIED_ZERO_SUPPORT'){call_inputs<-inputs;for(key in intersect(names(call_inputs),c('observed','target_weights','baseline_pd','outcome_predictions','log_odds_shifts','stabilization','trim')))call_inputs[[key]]<-as.numeric(unlist(call_inputs[[key]]));if(kind%in%c('IPW','AIPW'))call_inputs$propensities<-prop;computed<-do.call(methods[[kind]],call_inputs)$value};mismatch<-.va_differences(computed,record$result,tol);if(length(mismatch))violations[[length(violations)+1L]]<-list(result_id=record$result_id,code='SELECTION_ARTIFACT_RECONCILIATION',paths=as.list(mismatch));transported<-NULL;if(kind=='IPW'&&!is.null(computed))transported<-.mm_metrics(lapply(seq_along(rows),function(i)list(eligible=as.logical(factual[i]),weight=as.numeric(computed$weights[[i]]),target=outcomes[[i]],pd=predictions[[model]][i],cluster_id=rows[[i]]$cluster_id)));scenarios[[length(scenarios)+1L]]<-list(result_id=record$result_id,kind=kind,model_id=model,status=status,verified=!length(mismatch),recomputed_result=computed,overlap=overlap,ipw_metrics_conditional_mar=transported,empirical_full_population_validation=FALSE)}
 value<-.vb_result('selection_bias_sensitivity',list(evidence_scopes=measured$metrics,paired_candidate_minus_reference=measured$contrasts,through_the_door_count=length(rows),funded_count=sum(vapply(rows,function(r)r$funded,logical(1))),mature_factual_count=sum(factual)),d,rows,exclusions,bands,context,diagnostics=list(evaluation_plan=ev,transport_scenarios=scenarios,violations=violations,candidate_hashes=setNames(lapply(candidates,function(c)c$model_hash),vapply(candidates,function(c)c$model_id,character(1))),fitted_any_model=FALSE,counterfactual_policy_performance_identified=FALSE))$value;value$decision<-list(status=if(length(violations))'BLOCKED'else'NOT_ASSESSED',rule='ARTIFACT_RECONCILIATION_ONLY');.cr_result(value,'validation.selection_bias_sensitivity','validation_metrics',context,limitations='Observed funded, authorized exploration, synthetic engineering truth and transported external proxies remain separate. MAR, MNAR shifts, AIPW assumptions and bounds are assumptions, not observed rejected outcomes. Zero support does not identify a new policy. Intervals condition on frozen candidates and selection models.')
}
